SELECT CASE WHEN humidity >= 63 THEN 'LARGE' ELSE 'SMALL' END AS humidity_tier, device_code, APPROX_PERCENTILE(humidity, ARRAY(0.25, 0.5, 0.75)) AS humidity_quartiles, COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END) AS dv_01_count, AVG(status_bits) FILTER (WHERE device_code = 'DV-04') AS dv_04_avg_status_bits, COUNT_IF(device_code = 'DV-01') AS dv_01_events, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, MIN(reading_ts) AS started_at FROM device_readings GROUP BY CASE WHEN humidity >= 63 THEN 'LARGE' ELSE 'SMALL' END, device_code
